import re
from functools import cmp_to_key

def _parse_version(v_str):
    # 'v' önekini kaldır
    if v_str.startswith('v'):
        v_str = v_str[1:]

    # Regex ile core, pre-release ve build kısımlarını ayır
    # Format: MAJOR.MINOR.PATCH[-PRE_RELEASE][+BUILD]
    match = re.match(r'^([^+-]+)(?:\-(.*))?(?:\+(.*))?$', v_str)
    if not match:
        raise ValueError(f"Geçersiz versiyon formatı: {v_str}")

    core_part, pre_release, build = match.groups()

    # Core (MAJOR.MINOR.PATCH) ayrıştırma ve doğrulama
    core_parts = core_part.split('.')
    if len(core_parts) != 3:
        raise ValueError(f"Core kısmı MAJOR.MINOR.PATCH olmalıdır: {core_part}")

    parsed_core = []
    for p in core_parts:
        if not p.isdigit():
            raise ValueError(f"Core parçaları sayısal olmalıdır: {p}")
        # Baştaki sıfır kontrolü (0 hariç)
        if len(p) > 1 and p[0] == '0':
            raise ValueError(f"Baştaki sıfıra izin verilmez: {p}")
        parsed_core.append(int(p))

    # Pre-release ayrıştırma
    parsed_pre = None
    if pre_release is not None:
        parsed_pre = []
        for part in pre_release.split('.'):
            if part.isdigit():
                # Sayısal ise (tip 0, değer) olarak tutalım ki karşılaştırmada kolay olsun
                parsed_pre.append((0, int(part)))
            else:
                # Metinsel ise (tip 1, değer) olarak tutalım
                parsed_pre.append((1, part))

    return parsed_core, parsed_pre

def compare(a: str, b: str) -> int:
    """SemVer 2.0.0 kurallarına göre iki versiyonu karşılaştırır."""
    core_a, pre_a = _parse_version(a)
    core_b, pre_b = _parse_version(b)

    # 1. Core (Major, Minor, Patch) karşılaştırması
    for ca, cb in zip(core_a, core_b):
        if ca < cb:
            return -1
        if ca > cb:
            return 1

    # 2. Pre-release karşılaştırması
    # Eğer birinde pre-release var diğeri yoksa, pre-release olan daha küçüktür.
    if pre_a is None and pre_b is not None:
        return 1  # a > b (normal versiyon pre-release'den büyüktür)
    if pre_a is not None and pre_b is None:
        return -1 # a < b
    if pre_a is None and pre_b is None:
        return 0   # İkisi de normal versiyon ve core kısımları eşit

    # Her ikisinde de pre-release var, parça parça karşılaştır
    for pa, pb in zip(pre_a, pre_b):
        type_a, val_a = pa
        type_b, val_b = pb

        if type_a == 0 and type_b == 0: # İkisi de sayısal
            if val_a < val_b: return -1
            if val_a > val_b: return 1
        elif type_a != type_b: # Biri sayısal diğeri metinsel (Sayısal olan daha küçüktür)
            return -1 if type_a == 0 else 1
        else: # İkisi de metinsel
            if val_a < val_b: return -1
            if val_a > val_b: return 1

    # Eğer tüm parçalar eşitse, daha fazla parçası olan (daha uzun) versiyon büyüktür.
    if len(pre_a) < len(pre_b):
        return -1
    elif len(pre_a) > len(pre_b):
        return 1
    else:
        return 0

def sort_versions(versions: list[str]) -> list[str]:
    """Versiyonları SemVer kurallarına göre artan sırada sıralar."""
    # Python'un sorted() fonksiyonu kararlıdır (stable), bu yüzden eşit olanların sırası korunur.
    return sorted(versions, key=cmp_to_key(compare))

